    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, target in rules:
            index = 0
            while index < len(current):
                index = current.find(src, index)
                if index == -1:
